 async function account(ticket,earlyBilling){
  panelOrg=null;teamUsage=null;if(personalTab==='people'||!['models','keys','usage'].includes(personalTab))personalTab='models';
  if(current==='personal/usage')personalTab='usage';
  const pilotPromise=api('/api/pilot/status').catch(()=>({enabled:false}));
  const employeePromise=api('/api/employee-credit/status').catch(()=>({enabled:false}));
  try{if(earlyBilling){const result=await earlyBilling;if(result.error)throw result.error;personalBilling=result.data;}else personalBilling=await api('/api/billing/personal');}catch(e){if(e.status===401)throw e;personalBilling=null;}
  personalPilot=await pilotPromise;
  employeeCredit=await employeePromise;
  if(ticket!==generation)return;
  const usage=personalBilling?.usage_by_model||[];
  const pilotCalls=personalPilot?.enabled?(personalPilot.usage_by_model||[]).reduce((sum,row)=>sum+Number(row.successful_calls||0),0):0;
  const callCount=pilotCalls?pilotCalls.toLocaleString('zh-CN'):usage.length?usage.reduce((sum,row)=>sum+Number(row.calls||0),0).toLocaleString('zh-CN'):'—';
  const sideTab=(key,label,icon)=>`<button type="button" data-personal-tab data-live="personal-tab" data-tab="${key}" class="${personalTab===key?'active':''}" aria-label="${label}" aria-current="${personalTab===key?'page':'false'}">${ico(icon)}<span>${label}</span></button>`;
  mount(`<div class="personal-console">${customerHeader()}<aside class="pc-sidebar"><nav aria-label="个人工作台快捷入口">${sideTab('models','模型','layers')}${sideTab('keys','密钥','command')}${sideTab('usage','用量','chart-no-axes-combined')}<a href="#billing/personal" aria-label="账单">${ico('receipt-text')}<span>账单</span></a><a href="#security" aria-label="设置">${ico('settings')}<span>设置</span></a></nav></aside><div class="pc-stage"><div class="personal-console-stats"><div class="pc-stat-balance">${ico('server')}<span>可用余额</span><strong>${personalMoney(personalBilling?.cash_balance_fen)}</strong></div><div class="pc-stat-spent">${ico('receipt-text')}<span>累计已用</span><strong>${personalMoney(personalBilling?.total_spent_fen)}</strong></div><div class="pc-stat-calls">${ico('chart-no-axes-combined')}<span>模型调用</span><strong>${callCount}</strong></div><div class="pc-stat-budget">${ico('clock')}<span>本月预算</span><strong>未设置</strong></div><a class="personal-recharge" href="#billing/personal">${ico('server')} 充值</a></div>${employeeCreditBand()}<div data-personal-content>${personalDashboardContent()}</div></div></div>`);
 }
