  const grantNote=credit?'批准后自动获得 ¥10 公司额度':'批准后加入企业空间';
  const people=`<section class="org-card org-people-card"><div class="org-card-head"><div><span class="org-kicker">TEAM</span><h3>员工</h3><p>把邀请链接发给同事；他们验证邮箱并提交申请后，由管理者批准。</p></div><div>${!joinLink?btn(ico('plus')+' 生成邀请链接','create-join-link','','primary'):''} ${btn('刷新申请','refresh-join-requests','','quiet')}</div></div>${joinLink?`<div class="org-join-link"><label>当前邀请链接 · ${new Date(joinLink.expires_at).toLocaleDateString('zh-CN')} 到期<input type="text" readonly value="${esc(joinLink.url)}" aria-label="企业邀请链接"></label>${btn('复制链接','copy-join-link',`data-url="${esc(joinLink.url)}"`,'quiet')}${btn('撤销链接','revoke-join-link',`data-id="${joinLink.id}"`,'quiet')}</div>`:`<p class="live-small">尚未生成邀请链接。${grantNote}。</p>`}<div class="live-table-wrap org-table-wrap"><table><thead><tr><th>姓名与邮箱</th><th>身份</th><th>部门</th><th>账户状态</th><th>已用 / 额度</th><th>操作</th></tr></thead><tbody>${members.map(memberRow).join('')+pending.map(pendingRow).join('')}</tbody></table></div><div class="org-table-foot"><span>已启用 ${active} · 待审批 ${pending.length}</span><span>${grantNote}</span></div></section>`;
  const settings=`<div class="org-section-grid"><section class="org-card org-wide-card"><span class="org-kicker">企业资料</span><h3>${esc(o.name)}</h3><div class="org-setting-row"><span>我的身份</span><b>${customerRoles[m.role]||'企业成员'}</b></div><div class="org-setting-row"><span>权限范围</span><b>${manager?'管理全公司的员工、额度和用量':'使用自己的额度和 Key'}</b></div><div class="org-setting-row"><span>服务区域</span><b>${o.region==='CN'?'中国区':esc(o.region||'中国区')}</b></div></section><section class="org-card org-side-note"><span class="org-kicker">账户安全</span><h3>保护企业的访问</h3><p>管理自己的密码与登录设备。</p><a class="org-secondary-link" href="#security">账户安全 ${ico('arrow-up-right')}</a>${manager?btn('查看操作记录','org-audit','','quiet'):''}</section></div>`;
  const stat=(cls,icon,label,value)=>`<div class="${cls}">${ico(icon)}<span>${label}</span><strong>${value}</strong></div>`;
  const stats=team?stat('pc-stat-balance','server','公司可用',employeeYuan(team.totals.available_yuan))+stat('pc-stat-spent','receipt-text','本月消费',employeeYuan(team.totals.month_yuan))+stat('pc-stat-calls','chart-no-axes-combined','30 天调用',team.totals.calls_30d.toLocaleString('zh-CN'))+stat('pc-stat-budget','users-round','活跃员工',`${team.totals.active_members} / ${team.totals.members}`):credit?stat('pc-stat-balance','server','我的额度',employeeYuan(employeeCredit.available_yuan))+stat('pc-stat-spent','receipt-text','已结算',employeeYuan(employeeCredit.spent_yuan))+stat('pc-stat-calls','chart-no-axes-combined','结算中',employeeYuan(employeeCredit.held_yuan))+stat('pc-stat-budget','clock','发放',employeeYuan(employeeCredit.granted_yuan)):stat('pc-stat-balance','users-round','团队成员',String(active))+stat('pc-stat-spent','receipt-text','待审批',String(pending.length))+stat('pc-stat-calls','chart-no-axes-combined','模型调用','—')+stat('pc-stat-budget','clock','公司额度','未开通');
  if(['models','keys'].includes(orgTab))personalTab=orgTab;
